{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to compute the net stage-1 action values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a scalar bonus to the stage-1 Q-value of the action chosen in the previous trial to capture choice perseverance.",
      "params": [
        {
          "name": "stickiness",
          "bounds": [0, 5]
        }
      ],
      "evidence": "q_net_stick = q_net.copy()\nif prev_action_1 != -1:\n    q_net_stick[prev_action_1] += stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Decays the Q-value of the unchosen stage-2 action towards zero to model the forgetting of old information.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_2 = 1 - action_2[trial]\nq_stage2_mf[state_idx, unchosen_action_2] *= (1 - decay_rate)",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free Q-value using the stage-2 reward prediction error, scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambda_elig",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lambda_elig * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
